From cfb3a2892afab18d754563355e086df2a1c04b8b Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 00:38:49 +0100
Subject: [PATCH] editor: accept any private key type the password decrypts

The 802.1x TLS private key check only counted a decrypted key as valid
when it was RSA, so Save stayed disabled with the correct password for
an EC key. Treat any key that PEM or PKCS#12 decoding opens as valid.

BUG: 527463
---
 libs/editor/settings/security802-1x.cpp                | 10 +++-------
 .../settings/wifisecurities/security8021xsetting.cpp   | 10 +++-------
 2 files changed, 6 insertions(+), 14 deletions(-)

diff --git a/libs/editor/settings/security802-1x.cpp b/libs/editor/settings/security802-1x.cpp
index 4e844a595..7f157db1e 100644
--- a/libs/editor/settings/security802-1x.cpp
+++ b/libs/editor/settings/security802-1x.cpp
@@ -282,15 +282,12 @@ bool pkcs12CanDecrypt(const QString &path, const QString &password)
             X509 *cert = nullptr;
             STACK_OF(X509) *ca = nullptr;

-            auto alg = EVP_PKEY_NONE;
-            if (PKCS12_parse(pkcs12, password.toUtf8().data(), &pkey, &cert, &ca)) {
-                alg = EVP_PKEY_base_id(pkey);
-            }
+            const bool canDecrypt = PKCS12_parse(pkcs12, password.toUtf8().data(), &pkey, &cert, &ca) && pkey;
             PKCS12_free(pkcs12);
             EVP_PKEY_free(pkey);
             X509_free(cert);
             sk_X509_pop_free(ca, X509_free);
-            return alg == EVP_PKEY_RSA;
+            return canDecrypt;
         }
     }
     return false;
@@ -609,9 +606,8 @@ bool Security8021x::isValid() const
             fclose(fp);

             if (pkey) {
-                auto canDecrypt = EVP_PKEY_base_id(pkey) == EVP_PKEY_RSA;
                 EVP_PKEY_free(pkey);
-                return canDecrypt;
+                return true;
             }
         }

diff --git a/libs/editorqml/settings/wifisecurities/security8021xsetting.cpp b/libs/editorqml/settings/wifisecurities/security8021xsetting.cpp
index 83f732a06..1abae070e 100644
--- a/libs/editorqml/settings/wifisecurities/security8021xsetting.cpp
+++ b/libs/editorqml/settings/wifisecurities/security8021xsetting.cpp
@@ -111,15 +111,12 @@ bool Security8021xSetting::pkcs12CanDecrypt(const QString &path, const QString &
             X509 *cert = nullptr;
             STACK_OF(X509) *ca = nullptr;

-            auto alg = EVP_PKEY_NONE;
-            if (PKCS12_parse(pkcs12, password.toUtf8().data(), &pkey, &cert, &ca)) {
-                alg = EVP_PKEY_base_id(pkey);
-            }
+            const bool canDecrypt = PKCS12_parse(pkcs12, password.toUtf8().data(), &pkey, &cert, &ca) && pkey;
             PKCS12_free(pkcs12);
             EVP_PKEY_free(pkey);
             X509_free(cert);
             sk_X509_pop_free(ca, X509_free);
-            return alg == EVP_PKEY_RSA;
+            return canDecrypt;
         }
     }
     return false;
@@ -657,9 +654,8 @@ bool Security8021xSetting::isValid() const
             auto pkey = PEM_read_PrivateKey(fp, nullptr, nullptr, const_cast<char *>(m_tlsPrivateKeyPassword.toUtf8().data()));
             fclose(fp);
             if (pkey) {
-                auto canDecrypt = EVP_PKEY_base_id(pkey) == EVP_PKEY_RSA;
                 EVP_PKEY_free(pkey);
-                return canDecrypt;
+                return true;
             }
         }
     } else if (method == NetworkManager::Security8021xSetting::EapMethodLeap) {
